#!/usr/bin/env python3
"""Ржавый Рывок - 2D раннер (одиночный файл).

Запуск:  python rust_rush.py      (нужен pygame: pip install pygame)
Сгенерировано tools/build_single_file.py из game/ - не редактируйте вручную.
"""
import base64
import importlib.abc
import importlib.util
import os
import sys

_FILE = os.path.abspath(__file__)
_SOURCES = {
    'config': '"""Настройки игры: экран, физика, уровни, навыки героя."""\nimport os\nimport sys\n\n# В собранном exe файлы распаковываются во временную папку, поэтому данные\n# (save.json) пишутся рядом с самим exe.\nif getattr(sys, "frozen", False):\n    ROOT = os.path.dirname(os.path.abspath(sys.executable))\nelse:\n    ROOT = os.path.dirname(os.path.abspath(__file__))\nASSETS_DIR = os.path.join(ROOT, "assets")\n# Путь к сохранению можно переопределить (используется тестами).\nSAVE_PATH = os.environ.get("RUST_RUNNER_SAVE", os.path.join(ROOT, "save.json"))\n\nTITLE = "Ржавый Рывок"\nW, H = 1280, 720\nFPS = 60\n\n# Геометрия и физика\nGROUND_Y = 640            # линия бега (низ спрайта героя)\nHERO_X = 240              # экранная позиция героя (бежит на месте, мир движется)\nHERO_H = 170              # высота спрайта героя, px\nHERO_HIT_W = 56\nHERO_STAND_H = 140\nHERO_SLIDE_H = 64\nBASE_HP = 3\nINVULN_TIME = 1.2\nGRAVITY = 2600.0\nJUMP_VEL = 980.0          # высота прыжка ~170 px\nDOUBLE_JUMP_VEL = 860.0\nJUMP_BUFFER = 0.12\nSLIDE_MIN = 0.55\nPX_PER_M = 100.0          # 100 px = 1 метр дистанции\n\n# Высоты атак (центры снарядов)\nHIGH_Y = GROUND_Y - 125   # "в голову": пройдёт над скольжением, попадёт по стоящему\nLOW_Y = GROUND_Y - 22     # "по ногам": перепрыгивается\n\n# Прокачка героя: 5 навыков, каждый до 5 рангов, очки дают уровни героя\nSKILL_MAX = 5\nSKILLS = [\n    {"id": "hp", "name": "Броня", "desc": "+1 максимальное здоровье за ранг"},\n    {"id": "dmg", "name": "Плазмоган", "desc": "+1 урон выстрела за ранг"},\n    {"id": "rate", "name": "Перезарядка", "desc": "-8% задержки между выстрелами за ранг"},\n    {"id": "magnet", "name": "Магнит", "desc": "+40 px радиус сбора лома за ранг"},\n    {"id": "xp", "name": "Сборщик", "desc": "+20% опыта за ранг"},\n]\n\n\ndef xp_needed(hero_level):\n    """Сколько опыта нужно для перехода с hero_level на следующий уровень."""\n    return 100 + 60 * (hero_level - 1)\n\n\n# 4 уровня, у каждого свой фон, босс и темп. После 4-го уровня игра уходит в\n# бесконечный режим: уровни повторяются, сложность растёт с каждым кругом.\nLEVELS = [\n    dict(name="Ржавая пустошь", bg="bg_lvl1.jpg", boss_img="boss_lvl1.png",\n         boss_name="Ржавый Грейдер", length=900, boss_hp=36, boss_h=400,\n         patterns=["saw", "bolt", "mix"], speed=(430, 680),\n         accent=(255, 150, 60), boss_color=(150, 110, 80), sky=((60, 25, 15), (255, 150, 70))),\n    dict(name="Токсичное болото", bg="bg_lvl2.jpg", boss_img="boss_lvl2.png",\n         boss_name="Гнилой Хищник", length=1100, boss_hp=52, boss_h=380,\n         patterns=["acid", "spit", "spore"], speed=(450, 720),\n         accent=(150, 255, 60), boss_color=(60, 90, 40), sky=((10, 40, 10), (120, 200, 30))),\n    dict(name="Мёртвый город", bg="bg_lvl3.jpg", boss_img="boss_lvl3.png",\n         boss_name="Кибер-Жнец", length=1300, boss_hp=66, boss_h=420,\n         patterns=["stream", "blade"], speed=(470, 760),\n         accent=(220, 120, 255), boss_color=(60, 60, 80), sky=((30, 20, 60), (180, 90, 200))),\n    dict(name="Раскалённый завод", bg="bg_lvl4.jpg", boss_img="boss_lvl4.png",\n         boss_name="Железный Колосс", length=1500, boss_hp=85, boss_h=460,\n         patterns=["stomp", "fist", "barrage"], speed=(490, 800),\n         accent=(255, 90, 40), boss_color=(80, 70, 70), sky=((30, 10, 5), (230, 80, 20))),\n]\nBOSS_MAX_W = 520\n',
    'assets': '"""Загрузка арта. Если файла нет, рисуется временная процедурная графика,\nпоэтому игра запускается и без картинок (см. tools/prepare_assets.py)."""\nimport base64\nimport io\nimport os\n\nimport pygame\n\nfrom config import ASSETS_DIR, W, H, HERO_H, GROUND_Y, LEVELS, BOSS_MAX_W\n\ntry:  # арт, вшитый в одиночный файл (см. tools/build_single_file.py)\n    from _embedded_assets import ASSETS as _EMBEDDED\nexcept ImportError:\n    _EMBEDDED = {}\n\n_cache = {}\n\n\ndef _load(name, alpha=True):\n    if name in _EMBEDDED:\n        try:\n            raw = io.BytesIO(base64.b64decode(_EMBEDDED[name]))\n            img = pygame.image.load(raw, name)\n            return img.convert_alpha() if alpha else img.convert()\n        except pygame.error:\n            return None\n    path = os.path.join(ASSETS_DIR, name)\n    if not os.path.exists(path):\n        return None\n    try:\n        img = pygame.image.load(path)\n        return img.convert_alpha() if alpha else img.convert()\n    except pygame.error:\n        return None\n\n\ndef _cached(key, make):\n    if key not in _cache:\n        _cache[key] = make()\n    return _cache[key]\n\n\ndef _fit(img, max_w, max_h):\n    """Масштабирует картинку с сохранением пропорций, не больше max_w x max_h."""\n    w, h = img.get_size()\n    k = min(max_w / w, max_h / h)\n    return pygame.transform.smoothscale(img, (max(1, round(w * k)), max(1, round(h * k))))\n\n\n# ---------- фоны ----------\n\ndef _fallback_bg(idx):\n    top, bottom = LEVELS[idx]["sky"]\n    surf = pygame.Surface((W, H))\n    for y in range(H):\n        t = y / H\n        col = [int(top[i] + (bottom[i] - top[i]) * t) for i in range(3)]\n        pygame.draw.line(surf, col, (0, y), (W, y))\n    sun = LEVELS[idx]["sky"][1]\n    pygame.draw.circle(surf, (255, 240, 200), (int(W * 0.72), 260), 90)\n    pygame.draw.rect(surf, (25, 20, 22), (0, GROUND_Y - 10, W, H - GROUND_Y + 10))\n    for x in range(0, W, 160):\n        pygame.draw.rect(surf, sun, (x, GROUND_Y + 40, 80, 6))\n    return surf\n\n\ndef background(idx):\n    def make():\n        img = _load(LEVELS[idx]["bg"], alpha=False)\n        if img is None:\n            img = _fallback_bg(idx)\n        if img.get_size() != (W, H):\n            img = pygame.transform.smoothscale(img, (W, H))\n        return img\n    return _cached(("bg", idx), make)\n\n\n# ---------- герой ----------\n\ndef _fallback_hero(jump):\n    surf = pygame.Surface((120, HERO_H), pygame.SRCALPHA)\n    pygame.draw.rect(surf, (25, 25, 30), (30, 110, 26, 58))      # ноги\n    pygame.draw.rect(surf, (25, 25, 30), (62, 110 if not jump else 96, 26, 58))\n    pygame.draw.rect(surf, (80, 60, 40), (26, 150, 34, 16))       # ботинки\n    pygame.draw.rect(surf, (80, 60, 40), (62, 150 if not jump else 136, 34, 16))\n    pygame.draw.rect(surf, (80, 95, 60), (30, 60, 60, 60), border_radius=10)  # куртка\n    pygame.draw.polygon(surf, (190, 40, 40), [(30, 62), (90, 62), (84, 74), (40, 74)])  # шарф\n    pygame.draw.circle(surf, (150, 100, 80), (60, 40), 18)        # голова\n    pygame.draw.ellipse(surf, (235, 235, 240), (42, 14, 36, 22))  # волосы\n    pygame.draw.rect(surf, (120, 170, 190), (84, 70, 14, 40), border_radius=4)  # рука\n    pygame.draw.circle(surf, (80, 220, 255), (66, 38), 4)         # киберглаз\n    return surf\n\n\ndef hero_run():\n    def make():\n        img = _load("hero_run.png")\n        if img is None:\n            img = _fallback_hero(False)\n        return _fit(img, 10000, HERO_H)\n    return _cached("hero_run", make)\n\n\ndef hero_jump():\n    def make():\n        img = _load("hero_jump.png")\n        if img is None:\n            img = _fallback_hero(True)\n        return _fit(img, 10000, HERO_H)\n    return _cached("hero_jump", make)\n\n\ndef hero_slide():\n    def make():\n        base = hero_run()\n        w, h = base.get_size()\n        return pygame.transform.smoothscale(base, (int(w * 1.25), int(h * 0.5)))\n    return _cached("hero_slide", make)\n\n\n# ---------- боссы ----------\n\ndef _fallback_boss(idx):\n    cfg = LEVELS[idx]\n    h = cfg["boss_h"]\n    w = int(h * 0.8)\n    surf = pygame.Surface((w, h), pygame.SRCALPHA)\n    col = cfg["boss_color"]\n    pygame.draw.rect(surf, col, (w * 0.15, h * 0.3, w * 0.7, h * 0.6), border_radius=24)\n    pygame.draw.circle(surf, tuple(c // 2 for c in col), (w // 2, int(h * 0.18)), int(w * 0.24))\n    pygame.draw.circle(surf, cfg["accent"], (int(w * 0.42), int(h * 0.18)), 7)\n    pygame.draw.circle(surf, cfg["accent"], (int(w * 0.58), int(h * 0.18)), 7)\n    pygame.draw.rect(surf, tuple(c // 2 for c in col), (w * 0.05, h * 0.55, w * 0.18, h * 0.4), border_radius=10)\n    pygame.draw.rect(surf, tuple(c // 2 for c in col), (w * 0.77, h * 0.55, w * 0.18, h * 0.4), border_radius=10)\n    return surf\n\n\ndef boss(idx):\n    def make():\n        img = _load(LEVELS[idx]["boss_img"])\n        if img is None:\n            img = _fallback_boss(idx)\n        return _fit(img, BOSS_MAX_W, LEVELS[idx]["boss_h"])\n    return _cached(("boss", idx), make)\n',
    'audio': '"""Звуки генерируются кодом (без аудиофайлов). Без звуковой карты игра работает тихо."""\nimport array\nimport math\nimport random\n\nimport pygame\n\nRATE = 44100\n\n\ndef _gen(f0, f1, dur, wave="square", vol=0.2, noise=0.0, decay=2.0):\n    n = int(RATE * dur)\n    out = array.array("h")\n    phase = 0.0\n    tau = 2 * math.pi\n    for i in range(n):\n        p = i / n\n        f = f0 + (f1 - f0) * p\n        phase += tau * f / RATE\n        if wave == "square":\n            v = 1.0 if math.sin(phase) >= 0 else -1.0\n        elif wave == "saw":\n            v = 2.0 * ((phase / tau) % 1.0) - 1.0\n        else:\n            v = math.sin(phase)\n        if noise:\n            v = v * (1 - noise) + noise * random.uniform(-1, 1)\n        s = int(max(-1.0, min(1.0, v * (1 - p) ** decay)) * vol * 32767)\n        out.append(s)\n        out.append(s)\n    return pygame.mixer.Sound(buffer=out.tobytes())\n\n\nSPECS = {\n    "jump": (300, 900, 0.16, "square", 0.18, 0.0),\n    "double": (500, 1200, 0.14, "square", 0.18, 0.0),\n    "shoot": (1400, 300, 0.07, "saw", 0.10, 0.0),\n    "hit": (200, 60, 0.35, "saw", 0.35, 0.4),\n    "pickup": (900, 1400, 0.08, "square", 0.12, 0.0),\n    "boss_hit": (300, 150, 0.12, "square", 0.18, 0.3),\n    "break": (500, 80, 0.22, "square", 0.18, 0.5),\n    "boss_die": (400, 40, 1.2, "saw", 0.28, 0.2),\n    "warn": (800, 400, 0.6, "square", 0.16, 0.0),\n    "levelup": (400, 1500, 0.5, "square", 0.18, 0.0),\n    "select": (700, 900, 0.05, "square", 0.10, 0.0),\n}\n\n\nclass Sounds:\n    def __init__(self):\n        self.snd = {}\n        if pygame.mixer.get_init() is None:\n            return\n        for name, args in SPECS.items():\n            try:\n                self.snd[name] = _gen(*args)\n            except (pygame.error, ValueError):\n                pass\n\n    def play(self, name):\n        s = self.snd.get(name)\n        if s is not None:\n            s.play()\n',
    'save': '"""Сохранение прогресса героя (save.json рядом с игрой)."""\nimport copy\nimport json\nimport os\n\nfrom config import SAVE_PATH, SKILLS, SKILL_MAX, xp_needed\n\nDEFAULT = {\n    "hero_level": 1,\n    "xp": 0,\n    "points": 0,\n    "skills": {s["id"]: 0 for s in SKILLS},\n    "unlocked": 1,       # сколько уровней открыто (1..4)\n    "best_m": 0,\n    "runs": 0,\n    "bosses": 0,\n    "total_scrap": 0,\n}\n\n\nclass SaveData:\n    def __init__(self, data):\n        self.data = data\n\n    @classmethod\n    def load(cls):\n        data = copy.deepcopy(DEFAULT)\n        try:\n            with open(SAVE_PATH, encoding="utf-8") as f:\n                loaded = json.load(f)\n        except (OSError, ValueError):\n            loaded = {}\n        for key, default in DEFAULT.items():\n            if key == "skills":\n                continue\n            value = loaded.get(key, default)\n            data[key] = int(value) if isinstance(default, int) and isinstance(value, (int, float)) else default\n        skills = loaded.get("skills", {})\n        for s in SKILLS:\n            value = skills.get(s["id"], 0)\n            data["skills"][s["id"]] = min(SKILL_MAX, max(0, int(value))) if isinstance(value, (int, float)) else 0\n        data["unlocked"] = min(4, max(1, data["unlocked"]))\n        data["hero_level"] = max(1, data["hero_level"])\n        return cls(data)\n\n    def write(self):\n        tmp = SAVE_PATH + ".tmp"\n        try:\n            with open(tmp, "w", encoding="utf-8") as f:\n                json.dump(self.data, f, ensure_ascii=False, indent=2)\n            os.replace(tmp, SAVE_PATH)\n        except OSError:\n            pass  # нет прав на запись: игра продолжает работать без сохранения\n\n    def add_xp(self, amount):\n        """Начисляет опыт, возвращает количество полученных уровней героя."""\n        d = self.data\n        d["xp"] += amount\n        gained = 0\n        while d["xp"] >= xp_needed(d["hero_level"]):\n            d["xp"] -= xp_needed(d["hero_level"])\n            d["hero_level"] += 1\n            d["points"] += 1\n            gained += 1\n        return gained\n\n    def buy(self, skill_id):\n        d = self.data\n        if d["points"] <= 0 or d["skills"][skill_id] >= SKILL_MAX:\n            return False\n        d["points"] -= 1\n        d["skills"][skill_id] += 1\n        self.write()\n        return True\n',
    'entities': '"""Игровые объекты: герой, препятствия, снаряды, боссы, лом, частицы."""\nimport math\nimport random\n\nimport pygame\n\nfrom config import (\n    GROUND_Y, HERO_X, HERO_HIT_W, HERO_STAND_H, HERO_SLIDE_H, BASE_HP, INVULN_TIME,\n    GRAVITY, JUMP_VEL, DOUBLE_JUMP_VEL, JUMP_BUFFER, SLIDE_MIN, HIGH_Y, LOW_Y, W, H,\n)\n\n# ---------------- герой ----------------\n\n\nclass Hero:\n    def __init__(self, skills):\n        self.max_hp = BASE_HP + skills["hp"]\n        self.hp = self.max_hp\n        self.dmg = 1 + skills["dmg"]\n        self.fire_base = 0.30 * (0.92 ** skills["rate"])\n        self.magnet = 90 + 40 * skills["magnet"]\n        self.xp_mult = 1.0 + 0.2 * skills["xp"]\n        self.y = float(GROUND_Y)\n        self.vy = 0.0\n        self.on_ground = True\n        self.jumps = 0\n        self.jump_buf = 0.0\n        self.slide_t = 0.0\n        self.sliding = False\n        self.fire_cd = 0.0\n        self.invuln = 0.0\n        self.t = 0.0\n        self.events = []  # звуковые события для Play\n\n    def press_jump(self):\n        self.jump_buf = JUMP_BUFFER\n\n    def update(self, dt, down):\n        self.t += dt\n        self.fire_cd -= dt\n        self.invuln -= dt\n        if self.jump_buf > 0:\n            self.jump_buf -= dt\n        if self.jump_buf > 0 and (self.on_ground or self.jumps < 2):\n            if self.on_ground:\n                self.vy = -JUMP_VEL\n                self.jumps = 1\n                self.events.append("jump")\n            else:\n                self.vy = -DOUBLE_JUMP_VEL\n                self.jumps = 2\n                self.events.append("double")\n            self.on_ground = False\n            self.jump_buf = 0.0\n            self.slide_t = 0.0\n        if down:\n            if self.on_ground:\n                self.slide_t = SLIDE_MIN\n            elif self.vy < 1100:\n                self.vy = 1100.0  # быстрое падение вниз\n        if self.slide_t > 0:\n            self.slide_t = max(0.0, self.slide_t - dt)\n        self.sliding = self.on_ground and (down or self.slide_t > 0)\n        if not self.on_ground:\n            self.vy += GRAVITY * dt\n            self.y += self.vy * dt\n            if self.y >= GROUND_Y:\n                self.y = float(GROUND_Y)\n                self.vy = 0.0\n                self.on_ground = True\n                self.jumps = 0\n                self.events.append("land")\n\n    def hitbox(self):\n        h = HERO_SLIDE_H if self.sliding else HERO_STAND_H\n        return pygame.Rect(HERO_X - HERO_HIT_W // 2, int(self.y) - h, HERO_HIT_W, h)\n\n    def hurt(self):\n        if self.invuln > 0 or self.hp <= 0:\n            return False\n        self.hp -= 1\n        self.invuln = INVULN_TIME\n        return True\n\n    def can_fire(self):\n        return self.fire_cd <= 0 and self.hp > 0\n\n    def fire(self):\n        self.fire_cd = self.fire_base\n\n    def draw(self, s, img_run, img_jump, img_slide):\n        if self.invuln > 0 and int(self.t * 18) % 2 == 0:\n            return\n        if self.sliding:\n            img = img_slide\n            bob = 0\n        elif not self.on_ground:\n            img = img_jump\n            bob = 0\n        else:\n            img = img_run\n            bob = abs(math.sin(self.t * 15)) * 6\n        shadow_w = max(40, 90 - (GROUND_Y - self.y) * 0.25)\n        pygame.draw.ellipse(s, (20, 14, 14), (HERO_X - shadow_w / 2, GROUND_Y - 6, shadow_w, 12))\n        rect = img.get_rect(midbottom=(HERO_X, int(self.y - bob)))\n        s.blit(img, rect)\n\n\n# ---------------- препятствия ----------------\n\nOBS_DEFS = {\n    "crate": dict(w=64, h=64, bottom=GROUND_Y, breakable=True),\n    "spikes": dict(w=84, h=36, bottom=GROUND_Y, breakable=False),\n    "barrel": dict(w=54, h=76, bottom=GROUND_Y, breakable=False),\n    "beam": dict(w=110, h=70, bottom=GROUND_Y - 100, breakable=False),  # под неё скользят\n    "drone": dict(w=60, h=42, bottom=GROUND_Y - 79, breakable=True),    # летающий, скольжение\n}\n\n\nclass Obstacle:\n    def __init__(self, kind, x, accent):\n        d = OBS_DEFS[kind]\n        self.kind = kind\n        self.w, self.h, self.bottom = d["w"], d["h"], d["bottom"]\n        self.breakable = d["breakable"]\n        self.x = float(x)\n        self.accent = accent\n        self.alive = True\n        self.spent = False\n        self.t = 0.0\n\n    def rect(self):\n        return pygame.Rect(int(self.x), int(self.bottom - self.h), self.w, self.h)\n\n    def update(self, dt, speed):\n        self.x -= speed * dt\n        self.t += dt\n        if self.x < -self.w - 20:\n            self.alive = False\n\n    def draw(self, s):\n        r = self.rect()\n        k = self.kind\n        if k == "crate":\n            pygame.draw.rect(s, (120, 84, 48), r)\n            pygame.draw.rect(s, (70, 46, 26), r, 4)\n            pygame.draw.line(s, (70, 46, 26), r.topleft, r.bottomright, 4)\n            pygame.draw.line(s, (70, 46, 26), r.topright, r.bottomleft, 4)\n            pygame.draw.rect(s, self.accent, r.inflate(-14, -14), 2)\n        elif k == "spikes":\n            n = 3\n            for i in range(n):\n                x0 = r.x + i * r.w / n\n                pts = [(x0, r.bottom), (x0 + r.w / n / 2, r.top), (x0 + r.w / n, r.bottom)]\n                pygame.draw.polygon(s, (150, 150, 160), pts)\n                pygame.draw.polygon(s, (60, 60, 70), pts, 2)\n        elif k == "barrel":\n            pygame.draw.rect(s, (60, 95, 150), r, border_radius=10)\n            pygame.draw.rect(s, (30, 40, 70), r, 3, border_radius=10)\n            for yy in (r.top + 12, r.centery, r.bottom - 12):\n                pygame.draw.line(s, (30, 40, 70), (r.x, yy), (r.right, yy), 4)\n            pygame.draw.circle(s, self.accent, r.center, 9)\n        elif k == "beam":\n            pygame.draw.rect(s, (90, 90, 100), r)\n            s.set_clip(r)\n            for x in range(r.x - r.h, r.right, 28):\n                pygame.draw.line(s, (240, 200, 40), (x, r.bottom), (x + r.h, r.top), 12)\n            s.set_clip(None)\n            pygame.draw.rect(s, (40, 40, 48), r, 3)\n        elif k == "drone":\n            c = r.center\n            pygame.draw.circle(s, (50, 50, 60), c, 18)\n            pygame.draw.circle(s, (230, 60, 50), c, 5)\n            a = self.t * 30\n            for sign in (1, -1):\n                dx, dy = math.cos(a) * 28 * sign, math.sin(a) * 6\n                pygame.draw.line(s, (200, 200, 210), (c[0] - dx, c[1] - dy), (c[0] + dx, c[1] + dy), 4)\n\n\n# ---------------- снаряды врагов ----------------\n\n\nclass Shot:\n    """Снаряд босса. kind определяет вид и то, можно ли его сбить выстрелом."""\n\n    def __init__(self, kind, x, y, vx, vy=0.0, g=0.0, w=40, h=40, color=(255, 120, 60)):\n        self.kind = kind\n        self.x, self.y = float(x), float(y)\n        self.vx, self.vy, self.g = vx, vy, g\n        self.w, self.h = w, h\n        self.color = color\n        self.alive = True\n        self.t = 0.0\n        self.destroyable = kind not in ("saw", "wave", "fist")\n\n    def rect(self):\n        return pygame.Rect(int(self.x - self.w / 2), int(self.y - self.h / 2), self.w, self.h)\n\n    def update(self, dt):\n        self.t += dt\n        self.vy += self.g * dt\n        self.x += self.vx * dt\n        self.y += self.vy * dt\n        if self.g > 0 and self.y >= GROUND_Y - self.h / 2:\n            self.alive = False  # кислота упала на землю\n        if self.x < -150 or self.x > W + 400 or self.y > H + 100 or self.y < -300:\n            self.alive = False\n\n    def draw(self, s):\n        r = self.rect()\n        c = self.color\n        k = self.kind\n        if k == "saw":\n            cx, cy, R = int(self.x), int(self.y), self.w // 2\n            pygame.draw.circle(s, (190, 190, 200), (cx, cy), R)\n            for i in range(10):\n                a = self.t * 12 + i * math.pi / 5\n                pygame.draw.line(s, (235, 235, 245), (cx + math.cos(a) * (R - 8), cy + math.sin(a) * (R - 8)),\n                                 (cx + math.cos(a) * (R + 4), cy + math.sin(a) * (R + 4)), 5)\n            pygame.draw.circle(s, (60, 60, 70), (cx, cy), R // 3)\n        elif k == "wave":\n            pygame.draw.rect(s, c, r)\n            pygame.draw.rect(s, (255, 230, 150), r.inflate(-16, -16))\n            pygame.draw.rect(s, (120, 40, 10), r, 3)\n        elif k == "fist":\n            pygame.draw.rect(s, (120, 120, 130), r, border_radius=14)\n            pygame.draw.rect(s, (40, 40, 48), r, 4, border_radius=14)\n            for i in range(1, 4):\n                pygame.draw.line(s, (50, 50, 58), (r.x + i * r.w / 4, r.y + 10), (r.x + i * r.w / 4, r.bottom - 10), 3)\n        elif k == "rocket":\n            flame = [(r.left, r.centery - 7), (r.left - 22, r.centery), (r.left, r.centery + 7)]\n            pygame.draw.polygon(s, (255, 170, 60), flame)\n            pygame.draw.rect(s, (70, 70, 80), r, border_radius=6)\n        elif k == "blade":\n            cx, cy, R = int(self.x), int(self.y), self.w // 2\n            for i in range(2):\n                a = self.t * 18 + i * math.pi / 2\n                pygame.draw.line(s, (200, 240, 255), (cx - math.cos(a) * R, cy - math.sin(a) * R),\n                                 (cx + math.cos(a) * R, cy + math.sin(a) * R), 8)\n            pygame.draw.circle(s, c, (cx, cy), 8)\n        elif k == "bolt" or k == "bullet":\n            pygame.draw.rect(s, c, r, border_radius=10)\n            pygame.draw.rect(s, (255, 255, 255), r.inflate(-r.w // 2, -r.h // 2), border_radius=6)\n        else:  # spit, acid, spore\n            cx, cy, R = int(self.x), int(self.y), self.w // 2\n            pygame.draw.circle(s, c, (cx, cy), R)\n            pygame.draw.circle(s, (240, 255, 200), (cx - R // 3, cy - R // 3), max(2, R // 4))\n\n\n# ---------------- снаряды героя, лом, частицы ----------------\n\n\nclass Bullet:\n    def __init__(self, x, y, dmg, color):\n        self.x, self.y = float(x), float(y)\n        self.dmg = dmg\n        self.color = color\n        self.alive = True\n\n    def rect(self):\n        return pygame.Rect(int(self.x), int(self.y - 17), 26, 34)\n\n    def update(self, dt):\n        self.x += 1200 * dt\n        if self.x > W + 40:\n            self.alive = False\n\n    def draw(self, s):\n        pygame.draw.rect(s, self.color, (int(self.x), int(self.y - 4), 26, 8), border_radius=4)\n        pygame.draw.rect(s, (255, 255, 255), (int(self.x) + 6, int(self.y - 2), 14, 4), border_radius=2)\n\n\nclass Pickup:\n    def __init__(self, kind, x, y):\n        self.kind = kind  # "scrap" или "heart"\n        self.x, self.y = float(x), float(y)\n        self.alive = True\n        self.t = random.random() * 6\n\n    def rect(self):\n        return pygame.Rect(int(self.x - 14), int(self.y - 14), 28, 28)\n\n    def update(self, dt, speed, target, magnet):\n        self.t += dt\n        self.x -= speed * dt\n        dx, dy = target[0] - self.x, target[1] - self.y\n        dist = math.hypot(dx, dy)\n        if 0 < dist < magnet:\n            k = min(1.0, 700 * dt / dist)\n            self.x += dx * k\n            self.y += dy * k\n        if self.x < -40:\n            self.alive = False\n\n    def draw(self, s):\n        bob = math.sin(self.t * 5) * 3\n        cx, cy = int(self.x), int(self.y + bob)\n        if self.kind == "scrap":\n            pygame.draw.circle(s, (255, 205, 80), (cx, cy), 11)\n            pygame.draw.circle(s, (120, 80, 20), (cx, cy), 11, 2)\n            pygame.draw.circle(s, (120, 80, 20), (cx, cy), 4)\n            for i in range(6):\n                a = self.t * 3 + i * math.pi / 3\n                pygame.draw.circle(s, (255, 205, 80), (int(cx + math.cos(a) * 14), int(cy + math.sin(a) * 14)), 3)\n        else:\n            pygame.draw.circle(s, (230, 60, 70), (cx - 6, cy - 3), 8)\n            pygame.draw.circle(s, (230, 60, 70), (cx + 6, cy - 3), 8)\n            pygame.draw.polygon(s, (230, 60, 70), [(cx - 14, cy), (cx + 14, cy), (cx, cy + 14)])\n\n\nclass Particle:\n    def __init__(self, x, y, vx, vy, life, color, size, grav=500.0):\n        self.x, self.y, self.vx, self.vy = x, y, vx, vy\n        self.life = self.max_life = life\n        self.color = color\n        self.size = size\n        self.grav = grav\n\n    def update(self, dt):\n        self.vy += self.grav * dt\n        self.x += self.vx * dt\n        self.y += self.vy * dt\n        self.life -= dt\n\n    def draw(self, s):\n        k = max(0.0, self.life / self.max_life)\n        pygame.draw.circle(s, self.color, (int(self.x), int(self.y)), max(1, int(self.size * k)))\n\n\n# ---------------- боссы ----------------\n\n\nclass Boss:\n    """Босс стоит справа и атакует по сценариям-генераторам. Каждый сценарий\n    выдаёт паузы через yield; между сценариями есть перезарядка."""\n\n    def __init__(self, cfg, img, hp, cycle, out_list):\n        self.cfg = cfg\n        self.img = img\n        self.flash_img = img.copy()\n        self.flash_img.fill((90, 90, 90), special_flags=pygame.BLEND_RGB_ADD)\n        self.w, self.h = img.get_size()\n        self.x = W + self.w / 2 + 60\n        self.target_x = W - self.w / 2 - 40\n        self.bottom = GROUND_Y + 6\n        self.max_hp = hp\n        self.hp = hp\n        self.color = cfg["accent"]\n        self.out = out_list\n        self.patterns = cfg["patterns"]\n        self.cooldown = max(0.9, 1.6 - 0.2 * cycle)\n        self.arrived = False\n        self.wait = 1.2\n        self.flash = 0.0\n        self.dying = False\n        self.t = 0.0\n        self.last = None\n        self.routine = self._routine()\n\n    @property\n    def ox(self):\n        """Точка, из которой вылетают снаряды (примерно у головы/пушки)."""\n        return self.x - self.w * 0.35\n\n    def rect(self):\n        return pygame.Rect(int(self.x - self.w * 0.4), int(self.bottom - self.h * 0.9),\n                           int(self.w * 0.8), int(self.h * 0.9))\n\n    def hit(self, dmg):\n        self.hp -= dmg\n        self.flash = 0.08\n        return self.hp <= 0\n\n    def update(self, dt):\n        self.t += dt\n        self.flash -= dt\n        if self.dying:\n            return\n        if not self.arrived:\n            self.x -= 380 * dt\n            if self.x <= self.target_x:\n                self.x = self.target_x\n                self.arrived = True\n            return\n        self.wait -= dt\n        if self.wait <= 0:\n            try:\n                self.wait = next(self.routine)\n            except StopIteration:\n                self.wait = 999\n\n    def _routine(self):\n        while True:\n            options = [p for p in self.patterns if p != self.last] or self.patterns\n            name = random.choice(options)\n            self.last = name\n            yield from getattr(self, "p_" + name)()\n            ratio = self.hp / self.max_hp\n            yield self.cooldown * (0.7 if ratio < 0.5 else 1.0)\n\n    def shoot(self, kind, x, y, vx, vy=0.0, g=0.0, w=40, h=40, color=None):\n        self.out.append(Shot(kind, x, y, vx, vy, g, w, h, color or self.color))\n\n    # --- сценарии атак: уровень 1 (грейдер)\n    def p_saw(self):\n        for _ in range(2):\n            self.shoot("saw", self.ox, GROUND_Y - 28, -520, w=56, h=56, color=(200, 200, 210))\n            yield 0.8\n\n    def p_bolt(self):\n        for _ in range(3):\n            self.shoot("bolt", self.ox, HIGH_Y, -640, w=80, h=24)\n            yield 0.45\n\n    def p_mix(self):\n        self.shoot("saw", self.ox, GROUND_Y - 28, -520, w=56, h=56, color=(200, 200, 210))\n        yield 0.6\n        self.shoot("bolt", self.ox, HIGH_Y, -660, w=80, h=24)\n        yield 1.0\n\n    # --- уровень 2 (хищник)\n    def p_acid(self):\n        for _ in range(2):\n            sy, g, vy = GROUND_Y - 240, 1400.0, -380.0\n            y0 = sy - GROUND_Y\n            t_land = (-vy + math.sqrt(vy * vy - 2 * g * y0)) / g\n            target = HERO_X + random.uniform(40, 200)\n            vx = (target - self.ox) / t_land\n            self.shoot("acid", self.ox, sy, vx, vy=vy, g=g, w=34, h=34, color=(170, 255, 60))\n            yield 1.1\n\n    def p_spit(self):\n        for _ in range(3):\n            self.shoot("spit", self.ox, LOW_Y - 4, -720, w=44, h=26, color=(120, 230, 40))\n            yield 0.45\n\n    def p_spore(self):\n        for _ in range(3):\n            self.shoot("spore", self.ox, HIGH_Y, -440, w=30, h=30, color=(230, 230, 200))\n            yield 0.5\n\n    # --- уровень 3 (жнец)\n    def p_stream(self):\n        for i in range(6):\n            y = LOW_Y if i % 2 == 0 else HIGH_Y\n            self.shoot("bullet", self.ox, y, -900, w=44, h=12)\n            yield 0.5\n\n    def p_blade(self):\n        for _ in range(2):\n            self.shoot("blade", self.ox, HIGH_Y, -520, w=60, h=60, color=(200, 240, 255))\n            yield 0.9\n\n    # --- уровень 4 (колосс)\n    def p_stomp(self):\n        for _ in range(2):\n            self.shoot("wave", self.ox, GROUND_Y - 28, -480, w=60, h=56, color=(255, 140, 40))\n            yield 1.0\n\n    def p_fist(self):\n        self.shoot("fist", self.ox, GROUND_Y - 120, -380, w=110, h=90)\n        yield 0.9\n\n    def p_barrage(self):\n        for i in range(3):\n            y = LOW_Y if i % 2 else HIGH_Y\n            self.shoot("rocket", self.ox, y, -640, w=70, h=26, color=(255, 120, 40))\n            yield 0.5\n\n    def draw(self, s):\n        bob = math.sin(self.t * 2.2) * 4 if self.arrived else 0\n        img = self.flash_img if self.flash > 0 else self.img\n        s.blit(img, img.get_rect(midbottom=(int(self.x), int(self.bottom - bob))))\n',
    'ui': '"""Общие элементы интерфейса: текст, панели, меню."""\nimport pygame\n\nfrom config import W\n\n_fonts = {}\n\n\ndef font(size):\n    if size not in _fonts:\n        _fonts[size] = pygame.font.Font(None, size)\n    return _fonts[size]\n\n\ndef text(surf, s, size, pos, color=(255, 255, 255), anchor="topleft", alpha=255, shadow=True):\n    f = font(size)\n    img = f.render(s, True, color)\n    rect = img.get_rect()\n    setattr(rect, anchor, pos)\n    if shadow:\n        sh = f.render(s, True, (0, 0, 0))\n        if alpha < 255:\n            sh.set_alpha(alpha)\n        surf.blit(sh, rect.move(2, 2))\n    if alpha < 255:\n        img.set_alpha(alpha)\n    surf.blit(img, rect)\n    return rect\n\n\ndef panel(surf, rect, alpha=170, color=(12, 10, 14), border=(230, 140, 60)):\n    layer = pygame.Surface(rect.size, pygame.SRCALPHA)\n    layer.fill((*color, alpha))\n    surf.blit(layer, rect.topleft)\n    pygame.draw.rect(surf, border, rect, 2, border_radius=8)\n\n\ndef dim(surf, alpha=150):\n    layer = pygame.Surface(surf.get_size(), pygame.SRCALPHA)\n    layer.fill((0, 0, 0, alpha))\n    surf.blit(layer, (0, 0))\n\n\nclass Menu:\n    """Список кнопок с управлением клавиатурой (стрелки, Enter) и мышью."""\n\n    def __init__(self, items, top=300, spacing=66, width=380):\n        self.items = items  # [(надпись, функция), ...]\n        self.sel = 0\n        self.top = top\n        self.spacing = spacing\n        self.width = width\n\n    def rect(self, i):\n        return pygame.Rect(W // 2 - self.width // 2, self.top + i * self.spacing, self.width, 54)\n\n    def activate(self):\n        self.items[self.sel][1]()\n\n    def handle(self, e):\n        n = len(self.items)\n        if e.type == pygame.KEYDOWN:\n            if e.key == pygame.K_UP:\n                self.sel = (self.sel - 1) % n\n            elif e.key == pygame.K_DOWN:\n                self.sel = (self.sel + 1) % n\n            elif e.key in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE):\n                self.activate()\n        elif e.type == pygame.MOUSEMOTION:\n            for i in range(n):\n                if self.rect(i).collidepoint(e.pos):\n                    self.sel = i\n        elif e.type == pygame.MOUSEBUTTONDOWN and e.button == 1:\n            for i in range(n):\n                if self.rect(i).collidepoint(e.pos):\n                    self.sel = i\n                    self.activate()\n                    break\n\n    def draw(self, surf):\n        for i, (label, _) in enumerate(self.items):\n            r = self.rect(i)\n            sel = i == self.sel\n            layer = pygame.Surface(r.size, pygame.SRCALPHA)\n            layer.fill((255, 150, 60, 200) if sel else (20, 18, 24, 190))\n            surf.blit(layer, r.topleft)\n            pygame.draw.rect(surf, (255, 220, 160) if sel else (110, 90, 70), r, 2, border_radius=8)\n            text(surf, label, 36, r.center, (20, 15, 10) if sel else (235, 225, 210), anchor="center", shadow=False)\n',
    'play': '"""Игровая сцена: бесконечный бег, предупреждение о боссе, бой, гибель."""\nimport math\nimport random\n\nimport pygame\n\nimport assets\nfrom config import (\n    W, H, GROUND_Y, HERO_X, PX_PER_M, LOW_Y, HIGH_Y, LEVELS,\n)\nfrom entities import Hero, Obstacle, Shot, Bullet, Pickup, Particle, Boss  # noqa: F401\nfrom ui import text, panel, Menu\n\n\ndef lerp(a, b, t):\n    return a + (b - a) * t\n\n\ndef heart(s, cx, cy, size, color):\n    r = size / 4\n    pygame.draw.circle(s, color, (int(cx - r), int(cy - r / 2)), int(r))\n    pygame.draw.circle(s, color, (int(cx + r), int(cy - r / 2)), int(r))\n    pygame.draw.polygon(s, color, [(cx - size / 2, cy - r / 2), (cx + size / 2, cy - r / 2), (cx, cy + size / 2)])\n\n\nclass Play:\n    def __init__(self, app, idx, cycle=0):\n        self.app = app\n        self.idx = idx\n        self.cycle = cycle\n        self.cfg = LEVELS[idx]\n        self.accent = self.cfg["accent"]\n        self.hero = Hero(app.save.data["skills"])\n        self.bg = assets.background(idx)\n        self.img_run = assets.hero_run()\n        self.img_jump = assets.hero_jump()\n        self.img_slide = assets.hero_slide()\n        self.shade = pygame.Surface((W, H), pygame.SRCALPHA)\n        self.shade.fill((0, 0, 0, 70))\n        self.canvas = pygame.Surface((W, H))\n        self.streak_color = tuple(int(c * 0.7) for c in self.accent)\n        self.streaks = [[random.uniform(0, W), random.uniform(180, H), random.uniform(30, 90)] for _ in range(26)]\n\n        self.speed = float(self.cfg["speed"][0])\n        self.meters = 0.0\n        self.length = self.cfg["length"]\n        self.obstacles = []\n        self.shots = []\n        self.bullets = []\n        self.pickups = []\n        self.particles = []\n        self.obs_gap = 300.0\n        self.pick_timer = 0.8\n        self.phase = "run"          # run -> warn -> boss -> boss_dying | dying\n        self.phase_t = 0.0\n        self.boss = None\n        self.boss_down = False\n        self.kills = 0\n        self.scrap = 0\n        self.run_xp = 0\n        self.score = 0\n        self.banner = ""\n        self.banner_t = 0.0\n        self.banner_color = (255, 230, 160)\n        self.hint_t = 9.0\n        self.shake = 0.0\n        self.down_held = False\n        self.shoot_held = False\n        self.paused = False\n        self.done = False\n        self.t = 0.0\n        self.pause_menu = Menu([("Продолжить", self.resume),\n                                ("В меню (прогресс сохранится)", self.abandon)], top=360, width=440)\n        title = self.cfg["name"] + (f"  ·  круг {cycle + 1}" if cycle else "")\n        self.show_banner(f"УРОВЕНЬ {idx + 1}: {title}", 2.6)\n\n    # ---------- управление ----------\n\n    def show_banner(self, msg, dur, color=(255, 230, 160)):\n        self.banner, self.banner_t, self.banner_color = msg, dur, color\n\n    def resume(self):\n        self.paused = False\n\n    def abandon(self):\n        self.app.abandon_run(self)\n\n    def handle(self, e):\n        if e.type == pygame.KEYUP:\n            if e.key in (pygame.K_DOWN, pygame.K_s):\n                self.down_held = False\n            elif e.key in (pygame.K_x, pygame.K_z):\n                self.shoot_held = False\n            return\n        if e.type == pygame.MOUSEBUTTONUP and e.button == 1:\n            self.shoot_held = False\n            return\n        if self.paused:\n            if e.type == pygame.KEYDOWN and e.key == pygame.K_ESCAPE:\n                self.resume()\n            else:\n                self.pause_menu.handle(e)\n            return\n        if e.type == pygame.KEYDOWN:\n            if e.key in (pygame.K_SPACE, pygame.K_UP, pygame.K_w):\n                self.hero.press_jump()\n            elif e.key in (pygame.K_DOWN, pygame.K_s):\n                self.down_held = True\n            elif e.key in (pygame.K_x, pygame.K_z):\n                self.shoot_held = True\n            elif e.key == pygame.K_ESCAPE:\n                self.paused = True\n                self.pause_menu.sel = 0\n        elif e.type == pygame.MOUSEBUTTONDOWN:\n            if e.button == 1:\n                self.shoot_held = True\n            elif e.button == 3:\n                self.hero.press_jump()\n\n    # ---------- логика ----------\n\n    def update(self, dt):\n        if self.paused or self.done:\n            return\n        self.t += dt\n        self.phase_t += dt\n        if self.banner_t > 0:\n            self.banner_t -= dt\n        if self.hint_t > 0:\n            self.hint_t -= dt\n        self.shake = max(0.0, self.shake - dt * 40)\n\n        ph = self.phase\n        if ph == "run":\n            target = lerp(self.cfg["speed"][0], self.cfg["speed"][1],\n                          min(1.0, self.meters / self.length)) * (1 + 0.04 * self.cycle)\n            self.speed += (target - self.speed) * min(1.0, dt * 1.5)\n            self.meters += self.speed * dt / PX_PER_M\n            self.obs_gap -= self.speed * dt\n            if self.obs_gap <= 0:\n                self.spawn_obstacle()\n            self.pick_timer -= dt\n            if self.pick_timer <= 0:\n                self.spawn_pickups()\n                self.pick_timer = random.uniform(1.2, 2.4)\n            if self.meters >= self.length:\n                self.begin_warning()\n        elif ph == "warn":\n            self.speed += (120 - self.speed) * min(1.0, dt * 1.5)\n            if self.phase_t >= 2.4:\n                self.begin_boss()\n        elif ph == "boss":\n            self.speed = 0.0\n            self.boss.update(dt)\n            if self.boss.hp <= 0:\n                self.boss_defeated()\n        elif ph == "boss_dying":\n            self.speed = 0.0\n            self.boss.update(dt)\n            for _ in range(3):\n                r = self.boss.rect()\n                self.particles.append(Particle(random.uniform(r.left, r.right), random.uniform(r.top, r.bottom),\n                                               random.uniform(-120, 120), random.uniform(-260, -40),\n                                               random.uniform(0.5, 1.0), random.choice([(255, 200, 80), (255, 90, 40), (250, 250, 250)]),\n                                               random.randint(4, 9)))\n            if self.phase_t > 2.2:\n                self.end(True)\n                return\n        elif ph == "dying":\n            self.speed += (0.0 - self.speed) * min(1.0, dt * 3)\n            if self.phase_t > 1.4:\n                self.end(False)\n                return\n\n        self.hero.update(dt, self.down_held)\n        for ev in self.hero.events:\n            self.app.sfx.play(ev)\n        self.hero.events.clear()\n\n        if self.shoot_held and ph in ("run", "warn", "boss") and self.hero.can_fire():\n            self.hero.fire()\n            self.bullets.append(Bullet(HERO_X + 40, GROUND_Y - 70, self.hero.dmg, self.accent))\n            self.app.sfx.play("shoot")\n\n        hero_pt = (HERO_X, self.hero.y - 70)\n        for ob in self.obstacles:\n            ob.update(dt, self.speed)\n        for p in self.pickups:\n            p.update(dt, self.speed, hero_pt, self.hero.magnet)\n        for s in self.shots:\n            s.update(dt)\n        for b in self.bullets:\n            b.update(dt)\n        for p in self.particles:\n            p.update(dt)\n        for st in self.streaks:\n            st[0] -= self.speed * dt * 1.4\n            if st[0] < -120:\n                st[0] = W + random.uniform(0, 200)\n                st[1] = random.uniform(180, H)\n\n        self.obstacles = [o for o in self.obstacles if o.alive]\n        self.shots = [s for s in self.shots if s.alive]\n        self.bullets = [b for b in self.bullets if b.alive]\n        self.pickups = [p for p in self.pickups if p.alive]\n        self.particles = [p for p in self.particles if p.life > 0]\n\n        self.check_collisions()\n\n    def spawn_obstacle(self):\n        m = self.meters\n        pool = ["crate", "spikes", "barrel"]\n        if m > 60:\n            pool.append("drone")\n        if m > 120:\n            pool.append("beam")\n        kind = random.choice(pool)\n        x0 = W + 40\n        self.add_obstacle(kind, x0)\n        if kind in ("crate", "spikes", "barrel") and m > 150 and random.random() < 0.3:\n            # Два наземных препятствия подряд: прыжок и двойной прыжок\n            self.add_obstacle(random.choice(["crate", "spikes", "barrel"]), x0 + 230)\n        self.obs_gap = self.speed * random.uniform(0.9, 1.3) * (1 - 0.06 * min(self.cycle, 4))\n\n    def add_obstacle(self, kind, x):\n        self.obstacles.append(Obstacle(kind, x, self.accent))\n\n    def spawn_pickups(self):\n        row = random.choice([GROUND_Y - 30, GROUND_Y - 110, GROUND_Y - 160])\n        x0 = W + 40\n        n = random.randint(3, 5)\n        for i in range(n):\n            self.pickups.append(Pickup("scrap", x0 + i * 44, row))\n        if self.hero.hp < self.hero.max_hp and random.random() < 0.3:\n            self.pickups.append(Pickup("heart", x0 + n * 44, GROUND_Y - 30))\n\n    def begin_warning(self):\n        self.phase = "warn"\n        self.phase_t = 0.0\n        self.show_banner("ВНИМАНИЕ: БОСС!", 2.4, (255, 90, 70))\n        self.app.sfx.play("warn")\n\n    def begin_boss(self):\n        self.phase = "boss"\n        self.phase_t = 0.0\n        self.obstacles = []\n        self.pickups = []\n        hp = round(self.cfg["boss_hp"] * (1 + 0.5 * self.cycle))\n        self.boss = Boss(self.cfg, assets.boss(self.idx), hp, self.cycle, self.shots)\n        self.show_banner(self.cfg["boss_name"], 2.6, (255, 120, 90))\n\n    def boss_defeated(self):\n        self.phase = "boss_dying"\n        self.phase_t = 0.0\n        self.boss_down = True\n        self.boss.dying = True\n        self.shots.clear()\n        self.kills += 1\n        self.run_xp += int(250 * (1 + 0.5 * self.cycle) * self.hero.xp_mult)\n        self.score += 1000\n        self.show_banner("БОСС ПОВЕРЖЕН!", 2.2, (140, 255, 170))\n        self.app.sfx.play("boss_die")\n\n    def hero_dies(self):\n        self.phase = "dying"\n        self.phase_t = 0.0\n        self.explode(HERO_X, self.hero.y - 80, (255, 120, 60), n=30, speed=380)\n        self.app.sfx.play("hit")\n\n    def damage_hero(self):\n        if self.hero.hurt():\n            self.shake = 10.0\n            self.app.sfx.play("hit")\n            if self.hero.hp <= 0 and self.phase in ("run", "warn", "boss"):\n                self.hero_dies()\n            return True\n        return False\n\n    def explode(self, x, y, color, n=14, speed=260):\n        for _ in range(n):\n            a = random.uniform(0, math.tau)\n            v = random.uniform(0.3, 1.0) * speed\n            self.particles.append(Particle(x, y, math.cos(a) * v, math.sin(a) * v - 80,\n                                           random.uniform(0.4, 0.9), color, random.randint(3, 7)))\n\n    def check_collisions(self):\n        hb = self.hero.hitbox()\n        live = self.phase in ("run", "warn", "boss")\n        if live:\n            for ob in self.obstacles:\n                if not ob.spent and ob.rect().colliderect(hb):\n                    if self.damage_hero():\n                        ob.spent = True\n                        if ob.breakable:\n                            ob.alive = False\n                            self.explode(ob.rect().centerx, ob.rect().centery, (150, 110, 70), n=10)\n            for s in self.shots:\n                if s.alive and s.rect().colliderect(hb):\n                    s.alive = False\n                    self.damage_hero()\n            for p in self.pickups:\n                if p.alive and p.rect().colliderect(hb.inflate(30, 30)):\n                    p.alive = False\n                    if p.kind == "scrap":\n                        self.scrap += 1\n                        self.score += 10\n                        self.run_xp += int(6 * self.hero.xp_mult)\n                        self.app.sfx.play("pickup")\n                    else:\n                        self.hero.hp = min(self.hero.max_hp, self.hero.hp + 1)\n                        self.app.sfx.play("levelup")\n\n        for b in self.bullets:\n            if not b.alive:\n                continue\n            br = b.rect()\n            hit_obstacle = False\n            for ob in self.obstacles:\n                if ob.alive and ob.rect().colliderect(br):\n                    hit_obstacle = True\n                    if ob.breakable:\n                        ob.alive = False\n                        self.kills += 1\n                        self.score += 50\n                        self.run_xp += int(8 * self.hero.xp_mult)\n                        self.explode(ob.rect().centerx, ob.rect().centery, (150, 110, 70), n=10)\n                        self.app.sfx.play("break")\n                    break\n            if hit_obstacle:\n                b.alive = False\n                continue\n            for s in self.shots:\n                if s.alive and s.destroyable and s.rect().colliderect(br):\n                    s.alive = False\n                    b.alive = False\n                    self.explode(s.x, s.y, s.color, n=6, speed=160)\n                    break\n            if b.alive and self.boss and self.phase == "boss" and self.boss.rect().colliderect(br):\n                b.alive = False\n                self.explode(br.centerx, br.centery, (255, 220, 120), n=8)\n                self.boss.hit(b.dmg)\n                self.app.sfx.play("boss_hit")\n\n    # ---------- отрисовка ----------\n\n    def draw(self, s):\n        c = self.canvas\n        c.blit(self.bg, (0, 0))\n        c.blit(self.shade, (0, 0))\n        if self.speed > 30:\n            for x, y, ln in self.streaks:\n                pygame.draw.line(c, self.streak_color, (x, y), (x + ln * self.speed / 600, y), 2)\n        for p in self.pickups:\n            p.draw(c)\n        for ob in self.obstacles:\n            ob.draw(c)\n        if self.boss:\n            self.boss.draw(c)\n        for sh in self.shots:\n            sh.draw(c)\n        self.hero.draw(c, self.img_run, self.img_jump, self.img_slide)\n        for b in self.bullets:\n            b.draw(c)\n        for p in self.particles:\n            p.draw(c)\n        self.draw_hud(c)\n        if self.phase == "dying":\n            red = pygame.Surface((W, H), pygame.SRCALPHA)\n            red.fill((160, 20, 20, min(120, int(self.phase_t * 200))))\n            c.blit(red, (0, 0))\n        if self.paused:\n            layer = pygame.Surface((W, H), pygame.SRCALPHA)\n            layer.fill((0, 0, 0, 160))\n            c.blit(layer, (0, 0))\n            text(c, "ПАУЗА", 80, (W // 2, 230), (255, 220, 160), anchor="center")\n            self.pause_menu.draw(c)\n        ox = oy = 0\n        if self.shake > 0:\n            ox = random.randint(-int(self.shake), int(self.shake))\n            oy = random.randint(-int(self.shake), int(self.shake))\n        s.blit(c, (ox, oy))\n\n    def draw_hud(self, c):\n        d = self.app.save.data\n        # левая панель: здоровье и счёт\n        panel(c, pygame.Rect(16, 14, 310, 104), alpha=150)\n        if self.hero.max_hp <= 8:\n            for i in range(self.hero.max_hp):\n                heart(c, 38 + i * 32, 40, 24, (230, 60, 70) if i < self.hero.hp else (70, 60, 65))\n        else:\n            text(c, f"HP {max(0, self.hero.hp)} / {self.hero.max_hp}", 28, (30, 40), (240, 90, 90))\n        text(c, f"Счёт: {self.score}", 26, (30, 62))\n        text(c, f"Лом: {self.scrap}    Опыт: +{self.run_xp}", 24, (30, 92), (230, 220, 200))\n\n        # полоса прогресса уровня\n        bar = pygame.Rect(W // 2 - 300, 22, 600, 14)\n        pygame.draw.rect(c, (30, 25, 30), bar, border_radius=6)\n        ratio = min(1.0, self.meters / self.length)\n        pygame.draw.rect(c, self.accent, (bar.x, bar.y, int(bar.w * ratio), bar.h), border_radius=6)\n        pygame.draw.rect(c, (235, 225, 210), bar, 2, border_radius=6)\n        pygame.draw.polygon(c, (255, 70, 60), [(bar.right + 4, bar.y - 4), (bar.right + 16, bar.centery),\n                                               (bar.right + 4, bar.bottom + 4)])\n        text(c, f"{self.cfg[\'name\']}  ·  {int(self.meters)} / {self.length} м",\n             24, (W // 2, 46), anchor="midtop")\n\n        # правая панель: герой\n        panel(c, pygame.Rect(W - 250, 14, 236, 70), alpha=150)\n        text(c, f"Герой: ур. {d[\'hero_level\']}", 28, (W - 232, 30))\n        text(c, f"Очки навыков: {d[\'points\']}", 22, (W - 232, 62), (255, 220, 160))\n\n        # полоса здоровья босса\n        if self.boss and self.phase in ("boss", "boss_dying"):\n            bw = 560\n            bx = W // 2 - bw // 2\n            text(c, f"{self.cfg[\'boss_name\']}", 28, (W // 2, 84), (255, 200, 170), anchor="midtop")\n            pygame.draw.rect(c, (30, 15, 15), (bx, 116, bw, 14), border_radius=6)\n            hp_ratio = max(0.0, self.boss.hp / self.boss.max_hp)\n            pygame.draw.rect(c, (230, 60, 50), (bx, 116, int(bw * hp_ratio), 14), border_radius=6)\n            pygame.draw.rect(c, (235, 225, 210), (bx, 116, bw, 14), 2, border_radius=6)\n\n        if self.banner_t > 0:\n            alpha = int(255 * min(1.0, self.banner_t / 0.4))\n            text(c, self.banner, 66, (W // 2, 250), self.banner_color, anchor="center", alpha=alpha)\n        if self.hint_t > 0:\n            alpha = int(255 * min(1.0, self.hint_t / 2.0))\n            text(c, "Пробел/W - прыжок (дважды - двойной)   S - скольжение под балкой и дроном   "\n                    "X/Z - огонь   Esc - пауза", 22, (W // 2, H - 26), (240, 230, 220),\n                 anchor="midbottom", alpha=alpha)\n\n    # ---------- завершение ----------\n\n    def end(self, cleared):\n        self.done = True\n        self.app.end_run(self, cleared)\n',
    'scenes': '"""Меню: главное, выбор уровня, прокачка героя, итоги забега."""\nimport math\n\nimport pygame\n\nimport assets\nfrom config import W, H, LEVELS, SKILLS, SKILL_MAX, xp_needed\nfrom ui import text, panel, dim, Menu\n\n\nclass Scene:\n    def handle(self, e):\n        pass\n\n    def update(self, dt):\n        pass\n\n\nclass MainMenu(Scene):\n    def __init__(self, app):\n        self.app = app\n        self.t = 0.0\n        self.bg = assets.background(0)\n        self.hero = assets.hero_run()\n        self.menu = Menu([\n            ("Играть", self.play),\n            ("Выбор уровня", self.levels),\n            ("Прокачка героя", self.upgrades),\n            ("Выход", app.quit),\n        ], top=330)\n\n    def play(self):\n        self.app.sfx.play("select")\n        self.app.start_level(self.app.save.data["unlocked"] - 1, 0)\n\n    def levels(self):\n        self.app.set_scene(LevelSelect(self.app))\n\n    def upgrades(self):\n        self.app.set_scene(Upgrades(self.app))\n\n    def handle(self, e):\n        if e.type == pygame.KEYDOWN and e.key == pygame.K_ESCAPE:\n            return\n        self.menu.handle(e)\n\n    def update(self, dt):\n        self.t += dt\n\n    def draw(self, s):\n        s.blit(self.bg, (0, 0))\n        dim(s, 110)\n        text(s, "РЖАВЫЙ РЫВОК", 110, (W // 2, 120), (255, 170, 80), anchor="center")\n        text(s, "Бесконечный бег · 4 уровня · боссы · прокачка героя", 30, (W // 2, 200),\n             (235, 225, 210), anchor="center")\n        d = self.app.save.data\n        text(s, f"Герой: ур. {d[\'hero_level\']}   Очки навыков: {d[\'points\']}   "\n                f"Рекорд: {d[\'best_m\']} м   Уровней открыто: {d[\'unlocked\']}/4",\n             24, (W // 2, 250), (230, 220, 200), anchor="center")\n        self.menu.draw(s)\n        bob = abs(math.sin(self.t * 2)) * 6\n        s.blit(self.hero, self.hero.get_rect(midbottom=(W - 220, H - 40 - bob)))\n        text(s, "Управление: Пробел - прыжок, S - скольжение, X/Z - огонь, Esc - пауза",\n             22, (W // 2, H - 24), (200, 190, 180), anchor="center")\n\n\nclass LevelSelect(Scene):\n    def __init__(self, app):\n        self.app = app\n        items = []\n        for i, cfg in enumerate(LEVELS):\n            items.append((f"{i + 1}. {cfg[\'name\']}  ·  босс: {cfg[\'boss_name\']}", self.make(i)))\n        items.append(("Назад", self.back))\n        self.menu = Menu(items, top=250, spacing=72, width=700)\n        self.bg = assets.background(0)\n\n    def make(self, i):\n        def go():\n            if i < self.app.save.data["unlocked"]:\n                self.app.start_level(i, 0)\n        return go\n\n    def back(self):\n        self.app.go_menu()\n\n    def handle(self, e):\n        if e.type == pygame.KEYDOWN and e.key == pygame.K_ESCAPE:\n            self.back()\n            return\n        self.menu.handle(e)\n\n    def draw(self, s):\n        s.blit(self.bg, (0, 0))\n        dim(s, 140)\n        text(s, "ВЫБОР УРОВНЯ", 84, (W // 2, 110), (255, 170, 80), anchor="center")\n        unlocked = self.app.save.data["unlocked"]\n        for i in range(len(LEVELS)):\n            if i >= unlocked:\n                r = self.menu.rect(i)\n                panel(s, r, alpha=200, border=(90, 90, 90))\n                text(s, "закрыт: победите босса предыдущего уровня", 22, r.center, (150, 150, 150),\n                     anchor="center", shadow=False)\n        self.menu.draw(s)\n        text(s, "Enter - выбрать, Esc - назад", 22, (W // 2, H - 30), (200, 190, 180), anchor="center")\n\n\nclass Upgrades(Scene):\n    def __init__(self, app):\n        self.app = app\n        self.sel = 0\n        self.bg = assets.background(0)\n        self.back_rect = pygame.Rect(W // 2 - 150, H - 84, 300, 54)\n\n    def row(self, i):\n        return pygame.Rect(W // 2 - 430, 250 + i * 76, 860, 62)\n\n    def back(self):\n        self.app.go_menu()\n\n    def buy(self, i):\n        if i >= len(SKILLS):\n            self.back()\n            return\n        ok = self.app.save.buy(SKILLS[i]["id"])\n        self.app.sfx.play("pickup" if ok else "select")\n\n    def handle(self, e):\n        n = len(SKILLS)\n        if e.type == pygame.KEYDOWN:\n            if e.key == pygame.K_ESCAPE:\n                self.back()\n            elif e.key == pygame.K_UP:\n                self.sel = (self.sel - 1) % (n + 1)\n            elif e.key == pygame.K_DOWN:\n                self.sel = (self.sel + 1) % (n + 1)\n            elif e.key in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE):\n                self.buy(self.sel)\n        elif e.type == pygame.MOUSEMOTION:\n            for i in range(n):\n                if self.row(i).collidepoint(e.pos):\n                    self.sel = i\n        elif e.type == pygame.MOUSEBUTTONDOWN and e.button == 1:\n            for i in range(n):\n                if self.row(i).collidepoint(e.pos):\n                    self.sel = i\n                    self.buy(i)\n                    return\n            if self.back_rect.collidepoint(e.pos):\n                self.back()\n\n    def draw(self, s):\n        d = self.app.save.data\n        s.blit(self.bg, (0, 0))\n        dim(s, 150)\n        text(s, "ПРОКАЧКА ГЕРОЯ", 80, (W // 2, 70), (255, 170, 80), anchor="center")\n        need = xp_needed(d["hero_level"])\n        text(s, f"Уровень героя: {d[\'hero_level\']}     Опыт: {d[\'xp\']} / {need}     "\n                f"Очки навыков: {d[\'points\']}", 28, (W // 2, 160), (240, 230, 210), anchor="center")\n        bar = pygame.Rect(W // 2 - 300, 196, 600, 12)\n        pygame.draw.rect(s, (40, 35, 40), bar, border_radius=6)\n        pygame.draw.rect(s, (255, 150, 60), (bar.x, bar.y, int(bar.w * d["xp"] / need), bar.h), border_radius=6)\n\n        for i, sk in enumerate(SKILLS):\n            r = self.row(i)\n            rank = d["skills"][sk["id"]]\n            sel = i == self.sel\n            panel(s, r, alpha=200 if sel else 150, border=(255, 220, 160) if sel else (110, 90, 70))\n            text(s, sk["name"], 30, (r.x + 22, r.y + 9), (255, 230, 180) if sel else (235, 225, 210))\n            text(s, sk["desc"], 20, (r.x + 22, r.y + 40), (200, 190, 180), shadow=False)\n            for k in range(SKILL_MAX):\n                pip = pygame.Rect(r.right - 160 + k * 30, r.centery - 9, 22, 18)\n                pygame.draw.rect(s, (255, 150, 60) if k < rank else (60, 55, 60), pip, border_radius=4)\n                pygame.draw.rect(s, (30, 25, 30), pip, 1, border_radius=4)\n            status = "MAX" if rank >= SKILL_MAX else ("Enter: +1" if d["points"] > 0 else "нет очков")\n            text(s, status, 20, (r.right - 176, r.centery), (200, 190, 180), anchor="midright", shadow=False)\n\n        sel = self.sel == len(SKILLS)\n        panel(s, self.back_rect, alpha=220, border=(255, 220, 160) if sel else (110, 90, 70))\n        text(s, "Назад", 34, self.back_rect.center, (255, 230, 180), anchor="center")\n\n\nclass Result(Scene):\n    """Итоги забега. summary - dict из App.finish_run."""\n\n    def __init__(self, app, summary, snapshot):\n        self.app = app\n        self.s = summary\n        self.snap = snapshot\n        self.t = 0.0\n        if summary["cleared"]:\n            if summary["idx"] < len(LEVELS) - 1:\n                nxt = ("Дальше: " + LEVELS[summary["idx"] + 1]["name"], self.next_level)\n            else:\n                nxt = ("Следующий круг (бесконечный бег)", self.next_level)\n            items = [nxt, ("В меню", app.go_menu)]\n        else:\n            items = [("Заново", self.retry), ("В меню", app.go_menu)]\n        self.menu = Menu(items, top=500, width=520)\n\n    def next_level(self):\n        idx, cycle = self.s["idx"], self.s["cycle"]\n        if idx < len(LEVELS) - 1:\n            self.app.start_level(idx + 1, cycle)\n        else:\n            self.app.start_level(0, cycle + 1)\n\n    def retry(self):\n        self.app.start_level(self.s["idx"], self.s["cycle"])\n\n    def handle(self, e):\n        if e.type == pygame.KEYDOWN and e.key == pygame.K_r:\n            self.retry()\n            return\n        if e.type == pygame.KEYDOWN and e.key == pygame.K_ESCAPE:\n            self.app.go_menu()\n            return\n        self.menu.handle(e)\n\n    def update(self, dt):\n        self.t += dt\n\n    def draw(self, s):\n        s.blit(self.snap, (0, 0))\n        dim(s, 170)\n        s_ = self.s\n        title = "УРОВЕНЬ ПРОЙДЕН!" if s_["cleared"] else "ТЫ ПАЛ В БОЮ"\n        col = (140, 255, 170) if s_["cleared"] else (255, 110, 90)\n        text(s, title, 84, (W // 2, 110), col, anchor="center")\n        lines = [\n            f"Пройдено: {s_[\'meters\']} м   ·   уровень {s_[\'idx\'] + 1}" + (f"   ·   круг {s_[\'cycle\'] + 1}" if s_[\'cycle\'] else ""),\n            f"Уничтожено: {s_[\'kills\']}   ·   лом: {s_[\'scrap\']}   ·   опыт: +{s_[\'xp\']}",\n            f"Уровень героя: {s_[\'hero_level\']}" + (f"   (повышен на {s_[\'levels\']})" if s_[\'levels\'] else ""),\n            f"Очки навыков: {s_[\'points\']}   ·   рекорд: {s_[\'best_m\']} м",\n        ]\n        for i, ln in enumerate(lines):\n            text(s, ln, 30, (W // 2, 220 + i * 52), (240, 230, 210), anchor="center")\n        self.menu.draw(s)\n',
    'main': '"""Ржавый Рывок - 2D раннер на pygame.\n\nЗапуск:  python main.py\n"""\nimport os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\n\nimport pygame  # noqa: E402\n\nfrom audio import Sounds  # noqa: E402\nfrom config import FPS, TITLE, W, H  # noqa: E402\nfrom save import SaveData  # noqa: E402\nfrom scenes import MainMenu, Result  # noqa: E402\n\n\nclass App:\n    def __init__(self):\n        pygame.mixer.pre_init(44100, -16, 2, 512)\n        pygame.init()\n        self.fullscreen = False\n        self.screen = self._mode()\n        pygame.display.set_caption(TITLE)\n        self.clock = pygame.time.Clock()\n        self.save = SaveData.load()\n        self.sfx = Sounds()\n        self.running = True\n        self.scene = MainMenu(self)\n\n    def _mode(self):\n        flags = pygame.SCALED | (pygame.FULLSCREEN if self.fullscreen else 0)\n        return pygame.display.set_mode((W, H), flags)\n\n    def toggle_fullscreen(self):\n        self.fullscreen = not self.fullscreen\n        self.screen = self._mode()\n\n    # ----- переходы между сценами\n    def set_scene(self, scene):\n        self.scene = scene\n\n    def go_menu(self):\n        self.scene = MainMenu(self)\n\n    def start_level(self, idx, cycle=0):\n        from play import Play\n        self.scene = Play(self, idx, cycle)\n\n    def quit(self):\n        self.running = False\n\n    def finish_run(self, play, cleared):\n        """Сохраняет итоги забега и прогресс героя, возвращает сводку для экрана."""\n        d = self.save.data\n        xp = int(play.run_xp)\n        levels = self.save.add_xp(xp)\n        meters = int(play.meters)\n        d["best_m"] = max(d["best_m"], meters)\n        d["runs"] += 1\n        d["total_scrap"] += play.scrap\n        if play.boss_down:\n            d["bosses"] += 1\n        if cleared:\n            d["unlocked"] = max(d["unlocked"], min(4, play.idx + 2))\n        self.save.write()\n        if levels:\n            self.sfx.play("levelup")\n        return dict(meters=meters, kills=play.kills, scrap=play.scrap, xp=xp, levels=levels,\n                    cleared=cleared, idx=play.idx, cycle=play.cycle, hero_level=d["hero_level"],\n                    points=d["points"], best_m=d["best_m"])\n\n    def end_run(self, play, cleared):\n        summary = self.finish_run(play, cleared)\n        self.scene = Result(self, summary, self.screen.copy())\n\n    def abandon_run(self, play):\n        self.finish_run(play, False)\n        self.go_menu()\n\n    def run(self):\n        while self.running:\n            dt = min(self.clock.tick(FPS) / 1000.0, 0.05)\n            for e in pygame.event.get():\n                if e.type == pygame.QUIT:\n                    self.running = False\n                elif e.type == pygame.KEYDOWN and e.key == pygame.K_F11:\n                    self.toggle_fullscreen()\n                else:\n                    self.scene.handle(e)\n            self.scene.update(dt)\n            self.scene.draw(self.screen)\n            pygame.display.flip()\n\n\ndef main():\n    App().run()\n    pygame.quit()\n\n\nif __name__ == "__main__":\n    main()\n',
    '_embedded_assets': 'ASSETS = {}\n',
}


class _Finder(importlib.abc.MetaPathFinder):
    def find_spec(self, fullname, path, target=None):
        if fullname in _SOURCES:
            return importlib.util.spec_from_loader(fullname, _Loader(), origin=_FILE)
        return None


class _Loader(importlib.abc.Loader):
    def create_module(self, spec):
        return None  # стандартный модуль

    def exec_module(self, module):
        module.__file__ = _FILE
        code = compile(_SOURCES[module.__name__], _FILE, "exec")
        exec(code, module.__dict__)


sys.meta_path.insert(0, _Finder())

if __name__ == "__main__":
    import main as _game
    _game.main()
